/**
 * A user-facing error generated by Pi TinyChat (not Pi/OS). The browser translates
 * `key` with its current language; the raw `message` stays for compatibility.
 */
export class TinyChatError extends Error {
	/** @param {string} key @param {Record<string, unknown>} [params] */
	constructor(key, params = {}) {
		super(key);
		this.name = "TinyChatError";
		this.key = key;
		this.params = params;
	}
}
